"""Tokens per search (1st + 2nd call together) from the backend log lines of the single runs, 2026-10-26."""
import statistics as s
H = """7904/2050 7719/895 7698/945 7557/1388 7597/1035 7821/1207 7866/1794 7570/968 7627/834 7642/1674 7691/3159 7538/1001 7027/2187 7870/1030 7545/1721 7561/864 7614/1622 7215/565 7913/2019 7581/1963 6364/2123 7978/2276 7699/1688 7810/1560 7718/1797 7800/1535 7717/1542 7515/2136 7479/1644 7585/1159 7551/2172 7437/1976 7613/2459 7847/1008 8055/975 7267/1341 7774/1676 7682/877 7727/1034 7905/1234 7816/1160 7542/1094 7697/1883 7948/1043 7452/1836 7094/2178 7675/714 7719/1196 7158/1015 7925/1756 7631/2060 7603/995 7691/767 7647/1933 7756/1805 7688/2015 7270/1778"""
M = """6670/1800 6348/902 6457/1565 6510/929 6153/1781 6394/2169 6065/1585 6327/834 6302/913 6350/773 6483/1636 6486/1199 5942/2760 6606/905 6193/1760 6501/1749 6478/1543 6206/1677 6501/950 6313/1572 6342/2108 6774/2065 6556/1692 6349/1562 6358/1867 6608/1329 6336/1399 6420/2074 6013/1495 6279/1487 6384/1981 6321/1967 6391/1853 6599/2042 6556/1902 5900/770 6556/552 6541/1826 6419/1705 6312/2710 6623/831 6339/1183 6463/1537 6577/1548 6144/1788 5914/1453 6385/637 6419/1688 5792/1413 6761/880 6363/904 6142/1786 6364/1883 6289/514 6469/1731 6454/1843 6015/1762"""
import sys
pin, pout = float(sys.argv[1]), float(sys.argv[2])  # $ per million input / output tokens
for name, t in (('haiku', H), ('ml', M)):
    p = [tuple(map(int, x.split('/'))) for x in t.split()]
    i = s.mean(a for a, _ in p); o = s.mean(b for _, b in p)
    print(name, len(p), 'in %.0f out %.0f' % (i, o), '$/search %.5f' % ((i * pin + o * pout) / 1e6), 'per 1000 searches $%.2f' % ((i * pin + o * pout) / 1e3))
